/* ─── tamra-nuat — an accordion that is a Thai folding book (samut khoi) ────────────────────────────────────────
   Markup: a container [data-tamra-nuat] holding <details> sections, each a <summary> and its answer.
   Without the script it is a plain, quiet accordion. With it (.tn-on) the questions stand in a column and the book
   stands beside them: the front board, the section's panels (pleated when closed, flat when open), the back board.
   Prefix: .tn-                                                                                                     */

.tn {
  --tn-paper: var(--paper, #f3f0e8);
  --tn-rule: var(--rule, #cfcac0);
  --tn-q: var(--ink, #141312);
  --tn-q2: var(--ink-2, #4a4744);
  --tn-q3: var(--ink-3, #8a857d);
  --tn-accent: var(--accent, #c96f4a);
  --tn-font: "EB Garamond", "Noto Serif Thai", Georgia, serif;
  position: relative;
  color: var(--tn-q);
  font-family: var(--serif, "EB Garamond", Georgia, serif);
}

/* ─── without the script: a quiet accordion ─────────────────────────────────────────────────────────────────── */
.tn > details { border-top: 1px solid var(--tn-rule); }
.tn > details:last-of-type { border-bottom: 1px solid var(--tn-rule); }
.tn summary {
  display: flex;
  gap: .7em;
  align-items: baseline;
  padding: .85em 0;
  list-style: none;
  cursor: pointer;
  font-size: clamp(17px, 1.6vw, 20px);
  line-height: 1.3;
  color: var(--tn-q2);
  -webkit-tap-highlight-color: transparent;
}
.tn summary::-webkit-details-marker { display: none; }
.tn summary::marker { content: ''; }
.tn details[open] > summary { color: var(--tn-q); }
.tn summary:hover, .tn details.tn-hot > summary { color: var(--tn-q); }
.tn summary > :not(.tn-n) { flex: 1 1 auto; }
/* the open/closed mark: a plus whose upright folds away when the section is open */
.tn summary::after {
  content: '';
  flex: none;
  align-self: center;
  width: .62em; height: .62em;
  margin-left: auto;
  background:
    linear-gradient(currentColor, currentColor) center / 100% 1.5px no-repeat,
    linear-gradient(currentColor, currentColor) center / 1.5px 100% no-repeat;
  opacity: .7;
  transition: transform .35s cubic-bezier(.3, 0, .2, 1), background-size .35s cubic-bezier(.3, 0, .2, 1), opacity .2s;
}
.tn details[open] > summary::after { background-size: 100% 1.5px, 1.5px 0%; transform: rotate(180deg); }
.tn summary:hover::after, .tn details.tn-hot > summary::after { opacity: 1; }
