.tn summary:focus-visible { outline: 2px solid var(--tn-accent); outline-offset: 3px; border-radius: 2px; }
.tn-n {
  flex: none;
  min-width: 1.4em;
  font-size: .8em;
  color: var(--tn-q3);
  font-family: "Noto Serif Thai", "Thonburi", var(--tn-font);
}
.tn details[open] .tn-n { color: var(--tn-accent); }
.tn details > :not(summary):not(.tn-room) { margin: 0 0 1.1em 2.1em; color: var(--tn-q2); line-height: 1.55; font-size: 17px; }
.tn details > :not(summary):not(.tn-room) p { margin: 0 0 .7em; }
.tn-room { display: block; }

.tn-live {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden;
  clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

/* ─── with the script: the questions beside the book ────────────────────────────────────────────────────────── */
.tn.tn-on {
  padding-top: var(--tn-top, 0);
  padding-bottom: var(--tn-bottom, 0);
}
.tn.tn-on > details {
  position: relative;
  box-sizing: border-box;
  width: var(--tn-qw);
  border: 0;
  overflow: visible;
}
.tn.tn-on > details::before {                 /* the hairline from the question to its crease */
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: calc(100% + var(--tn-gap));
  height: 1px;
  background: var(--tn-rule);
}
.tn.tn-on > details:first-of-type::before { display: none; }
.tn.tn-on summary {
  position: sticky;            /* an open question stays beside its panels while they scroll past */
  top: var(--tn-stick, 14px);
  padding: .55em 0 .6em;
  font-size: var(--tn-sum, clamp(15px, 1.5vw, 19px));
}
/* the answer is written in the book: its real text stays in the page for readers, find-in-page and print */
.tn.tn-on > details.tn-drawn > :not(summary):not(.tn-room) {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden;
  clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.tn-book {
  position: absolute;
  top: 0;
  right: 0;
  width: var(--tn-bw);
  pointer-events: none;
  filter: drop-shadow(0 1px 1px rgba(40, 30, 20, .18)) drop-shadow(0 6px 14px rgba(40, 30, 20, .10));
}
.tn-cover, .tn-board, .tn-p, .tn-edge {
  position: absolute;
  top: 0; left: 0;
  width: 100%;
  display: block;
  user-select: none;
  -webkit-user-select: none;
}
.tn-cover, .tn-board { height: auto; }
.tn-board { will-change: transform; }
.tn-p {
  pointer-events: auto;
  cursor: pointer;
  backface-visibility: hidden;
  will-change: transform;
}
.tn-p > img { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.tn-cr { position: absolute; left: .6%; right: .6%; pointer-events: none; }
.tn-tx { position: absolute; inset: 0; pointer-events: none; }
.tn-tx { font-family: var(--tn-font); }
.tn-l {
  position: absolute;
  white-space: pre;
  font-family: var(--tn-font);
  font-size: inherit;
  line-height: inherit;
  color: var(--tn-ink, #4f4034);
  font-kerning: normal;
}
.tn-edge { overflow: hidden; }
.tn-edge > img { width: 100%; height: auto; display: block; transform-origin: 0 0; }

/* narrow: each question above its own pleats, the answer in the page's type under its opening */
.tn.tn-on.tn-narrow > details { width: 100%; }
.tn.tn-on.tn-narrow > details::before { width: 100%; }
.tn.tn-on.tn-narrow > details:first-of-type::before { display: none; }
.tn.tn-on.tn-narrow summary { position: static; flex-wrap: wrap; font-size: var(--tn-sum, 17px); padding: .7em 0 .5em; }
.tn.tn-on.tn-narrow .tn-room { flex: 0 0 100%; order: 99; margin-top: .55em; }
.tn.tn-on:not(.tn-narrow) .tn-room { display: none; }
.tn.tn-on.tn-narrow > details > :not(summary):not(.tn-room) {
  margin: .9em 0 1.3em;
  font-size: 16.5px;
  line-height: 1.55;
  animation: tn-in .6s .15s both cubic-bezier(.3, 0, .2, 1);
}
@keyframes tn-in { from { opacity: 0; transform: translateY(-6px); } }

@media (prefers-reduced-motion: reduce) {
  .tn-p, .tn-board { will-change: auto; }
  .tn.tn-on.tn-narrow > details > :not(summary):not(.tn-room) { animation: none; }
}
@media print {
  .tn-book { display: none; }
  .tn.tn-on { padding: 0; }
  .tn.tn-on > details { width: auto; height: auto !important; }
  .tn-room { display: none; }
  .tn.tn-on > details.tn-drawn > :not(summary) { position: static; width: auto; height: auto; clip: auto; white-space: normal; margin: 0 0 1em 2.1em; }
}

